noten = [2, 1, 3, 2]

for note in noten:
    print(f"Note: {note}")

if 5 in noten:
    print("Achtung, ein Fünfer!")
else:
    print("Kein Fünfer dabei.")

schnitt = sum(noten) / len(noten)
print(f"Schnitt: {schnitt}")      # Schnitt: 2.0
print(f"Beste Note: {min(noten)}")  # Beste Note: 1

spieler = ["Lena", "Tom", "Sara"]
for i in range(len(spieler)):
    print(f"Platz {i + 1}: {spieler[i]}")

